import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

/**
 * File storage for user uploads (expense receipts for now). Abstract so the backend can move to
 * object storage (S3 / GCS, a Phase 2 gap) by adding one class. Keys are generated by the
 * backend, e.g. `receipts/<groupId>/<expenseId>/<uuid>.jpg`, never taken from the client.
 */
export abstract class StorageService {
  abstract put(key: string, data: Buffer, contentType: string): Promise<void>;
  /** null if the file doesn't exist. */
  abstract get(key: string): Promise<Buffer | null>;
  /** No error if it doesn't exist. */
  abstract delete(key: string): Promise<void>;
  /** Deletes everything under a "folder", e.g. all receipts of a deleted group. */
  abstract deletePrefix(prefix: string): Promise<void>;
}

/**
 * Stores files on the API server's disk under UPLOAD_DIR (default `./uploads`). Fine for dev and
 * a single server; files are lost if the server's disk is. Switch to object storage before launch.
 */
@Injectable()
export class LocalDiskStorageService extends StorageService {
  private readonly logger = new Logger(LocalDiskStorageService.name);
  private readonly root: string;

  constructor(config: ConfigService) {
    super();
    this.root = resolve(config.get<string>('UPLOAD_DIR')?.trim() || 'uploads');
  }

  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data);
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathFor(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }

  async deletePrefix(prefix: string): Promise<void> {
    await rm(this.pathFor(prefix), { recursive: true, force: true }).catch((err: Error) =>
      this.logger.warn(`Couldn't delete ${prefix}: ${err.message}`),
    );
  }

  // Guards against path traversal even though keys are generated server-side.
  private pathFor(key: string): string {
    const path = resolve(this.root, key);
    if (!path.startsWith(this.root + sep)) throw new Error(`Invalid storage key: ${key}`);
    return path;
  }
}
